insert into public.docs (path, data) values ('library/bloque1', $plan${"title": "1 · Base y tests (oct-dic · 9 sem)", "desc": "19 oct - 20 dic 2026. Aterrizaje, control, estiramiento, densidad y pico. Tests en semanas 1, 2 y 9.", "weeks": 9, "weekInfo": [{"phase": "Aterrizaje", "rir": "3", "note": "Aprende a medir el RIR y haz los tests. Elige el peso con el que te queden 3 repeticiones en reserva."}, {"phase": "Aterrizaje", "rir": "3", "note": "Aprende a medir el RIR y haz los tests. Elige el peso con el que te queden 3 repeticiones en reserva."}, {"phase": "Control", "rir": "2", "note": "Controla cada repetición: bajada lenta y pausas. Calidad antes que peso."}, {"phase": "Control", "rir": "2", "note": "Controla cada repetición: bajada lenta y pausas. Calidad antes que peso."}, {"phase": "Estiramiento", "rir": "2", "note": "Más estímulo en la parte estirada del músculo: parciales al final de algunas series."}, {"phase": "Estiramiento", "rir": "1", "note": "Más estímulo en la parte estirada del músculo: parciales al final de algunas series."}, {"phase": "Densidad", "rir": "1", "note": "Más trabajo en el mismo tiempo: drop sets y myo-reps en máquinas y poleas."}, {"phase": "Densidad", "rir": "1", "note": "Más trabajo en el mismo tiempo: drop sets y myo-reps en máquinas y poleas."}, {"phase": "Pico", "rir": "1", "note": "Última semana del bloque: máximo esfuerzo con técnica limpia, y retest."}], "days": [{"id": "A", "name": "Banca y dominadas", "dur": "~70 min", "warm": [{"n": "Movilidad · Rotación torácica a cuatro apoyos", "d": "8 por lado"}, {"n": "Movilidad · Deslizamientos de escápula en la pared", "d": "10 reps"}, {"n": "Activación · Flexiones lentas con escápulas controladas", "d": "8 reps"}, {"n": "Activación · Dead bug", "d": "8 por lado"}], "notes": ["", "", "", "", "", "", "", "", ""], "ex": [{"id": "A1", "name": "Press banca", "uni": false, "tempo": "Bajada de 2 s", "rest": "2-3 min", "cue": "Escápulas juntas y abajo, pies firmes y muñecas rectas. Baja la barra al pecho y sube sin despegar los glúteos del banco.", "why": "Pecho, hombro anterior y tríceps. Es tu empuje principal.", "warn": "Usa los seguros del rack o pide ayuda. Sin seguros ni ayuda, no vayas al fallo. Dolor de hombro o pectoral (no cansancio): para y avísame.", "hip": "", "wk": [{"s": 4, "r": "6", "kg": "", "n": "", "test": "rm5"}, {"s": 4, "r": "6", "kg": "", "n": ""}, {"s": 4, "r": "6", "kg": "", "n": ""}, {"s": 4, "r": "6", "kg": "", "n": ""}, {"s": 5, "r": "6", "kg": "", "n": ""}, {"s": 5, "r": "6", "kg": "", "n": ""}, {"s": 5, "r": "6", "kg": "", "n": ""}, {"s": 5, "r": "6", "kg": "", "n": ""}, {"s": 5, "r": "6", "kg": "", "n": "Última serie: RIR 0-1 (muy cerca del fallo con técnica limpia).", "test": "rm5"}]}, {"id": "A2", "name": "Remo con pecho apoyado", "uni": false, "tempo": "Sube y aguanta 1 s", "rest": "2 min", "cue": "Pecho pegado al banco, tira con los codos hacia atrás y junta las escápulas. Sin impulso.", "why": "Espalda media y dorsal. Compensa todo el trabajo de empuje.", "warn": "Cuello relajado, sin encogerte de hombros. Dolor de hombro o codo (no cansancio): para y avísame.", "hip": "", "wk": [{"s": 4, "r": "8", "kg": "", "n": "", "test": "rm5"}, {"s": 4, "r": "8", "kg": "", "n": ""}, {"s": 4, "r": "8", "kg": "", "n": ""}, {"s": 4, "r": "8", "kg": "", "n": ""}, {"s": 4, "r": "8", "kg": "", "n": ""}, {"s": 4, "r": "8", "kg": "", "n": ""}, {"s": 4, "r": "8", "kg": "", "n": ""}, {"s": 4, "r": "8", "kg": "", "n": ""}, {"s": 4, "r": "8", "kg": "", "n": "Última serie: RIR 0-1 (muy cerca del fallo con técnica limpia).", "test": "rm5"}]}, {"id": "A3", "name": "Press militar con mancuernas", "uni": false, "tempo": "Bajada de 2 s", "rest": "2 min", "cue": "Costillas abajo y glúteos apretados para no arquear la zona lumbar. Sube en línea recta.", "why": "Hombro y tríceps.", "warn": "Si notas dolor delante del hombro o la zona lumbar se arquea, para la serie y baja el peso.", "hip": "", "wk": [{"s": 3, "r": "8", "kg": "", "n": ""}, {"s": 3,